21		"github.com/entireio/cli/cmd/entire/cli/gitrepo"
22		"github.com/entireio/cli/cmd/entire/cli/logging"
23		"github.com/entireio/cli/cmd/entire/cli/osroot"
24		"github.com/entireio/cli/cmd/entire/cli/paths"
25		"github.com/entireio/cli/cmd/entire/cli/trailers"
26	)
27	
28	// maxReplacedCommits bounds how many dropped commits a redo considers.
29	const maxReplacedCommits = 200
30	
31	// inheritReplacedCommitsTrailers carries checkpoint trailers from commits this
32	// commit re-does. After `git reset` and a new commit, the dropped commits are
33	// the ones the reset left unreachable from every branch and remote (see
34	// replacedCommits). A dropped commit is inherited when every file it changed
35	// that is staged now has exactly the content it had before the reset: the work
36	// is recommitted, not rewritten, and one coincidentally identical file among
37	// rewritten ones is not a redo. Returns the inherited IDs, nil when nothing
38	// applies.
39	func (s *ManualCommitStrategy) inheritReplacedCommitsTrailers(ctx context.Context, repo *git.Repository, commitMsgFile, source string) []id.CheckpointID {
40		logCtx := logging.WithComponent(ctx, "checkpoint")
41		logging.Debug(logCtx, "prepare-commit-msg: checking for redone commits")
42		tip, replaced, why := replacedCommits(ctx, repo)
43		if len(replaced) == 0 {
44			logging.Debug(logCtx, "prepare-commit-msg: no commits being redone", slog.String("reason", why))
45			return nil
46		}
47		staged, err := stagedBlobs(ctx)
48		if err != nil || len(staged) == 0 {
49			logging.Debug(logCtx, "prepare-commit-msg: redo check has no staged blobs to compare",
50				slog.Int("replaced_commits", len(replaced)), slog.Any("error", err))
51			return nil
52		}
53		tipTree, err := tip.Tree()
54		if err != nil {
55			return nil
56		}
57		var inherited []id.CheckpointID
58		seen := make(map[id.CheckpointID]bool)
59		for i := len(replaced) - 1; i >= 0; i-- { // oldest first, like a squash message
60			if !recommitsFilesOf(replaced[i], tipTree, staged) {
61				continue
62			}
63			for _, cpID := range trailers.ParseAllCheckpoints(replaced[i].Message) {
64				if !seen[cpID] {
65					seen[cpID] = true
66					inherited = append(inherited, cpID)
67				}
68			}
69		}
70		inherited = withoutDeletedCheckpoints(ctx, inherited)
71		if len(inherited) == 0 {
72			logging.Debug(logCtx, "prepare-commit-msg: redone commits carry no matching trailers",
73				slog.Int("replaced_commits", len(replaced)), slog.Int("staged", len(staged)))
74			return nil
75		}
76		content, err := os.ReadFile(commitMsgFile) //nolint:gosec // commitMsgFile is provided by git hook
77		if err != nil {
78			return nil
79		}
80		message := string(content)
81		present := make(map[id.CheckpointID]bool)
82		for _, cpID := range trailers.ParseAllCheckpoints(message) {
83			present[cpID] = true
84		}
85		added := 0
86		for _, cpID := range inherited {
87			if !present[cpID] {
88				message = addInheritedCheckpointTrailer(message, cpID, source)
89				added++
90			}
91		}
92		if added > 0 {
93			if err := os.WriteFile(commitMsgFile, []byte(message), 0o600); err != nil { //nolint:gosec // path from git hook arg
94				return nil
95			}
96		}
97		logging.Info(logCtx, "prepare-commit-msg: inherited checkpoint trailers from the commits being redone",
98			slog.Int("replaced_commits", len(replaced)),
99			slog.Int("inherited", len(inherited)),
100			slog.Int("added", added))
101		return inherited
102	}
103	
104	// withRedoneTrailers adds the trailers of the commits this one redoes to the
105	// message and to inherited, and records the combined set for post-commit.
106	func (s *ManualCommitStrategy) withRedoneTrailers(ctx context.Context, repo *git.Repository, commitMsgFile, source string, inherited []id.CheckpointID) []id.CheckpointID {
107		redone := s.inheritReplacedCommitsTrailers(ctx, repo, commitMsgFile, source)
108		if len(redone) == 0 {
109			return inherited
110		}
111		inherited = append(inherited, redone...)
112		recordInheritedTrailers(ctx, inherited)
113		return inherited
114	}
115	
116	// prepareAmendCommitMsg keeps or restores the amended commit's own trailer and
117	// folds in a reset-dropped commit's trailers: `git reset --soft HEAD~1 && git
118	// commit --amend` squashes the last two commits, and the amended commit carries
119	// the work of both.
120	func (s *ManualCommitStrategy) prepareAmendCommitMsg(ctx context.Context, commitMsgFile string, strippedDeleted bool) error {
121		if err := s.handleAmendCommitMsg(ctx, commitMsgFile, strippedDeleted); err != nil {
122			return err
123		}
124		repo, err := OpenRepository(ctx)
125		if err != nil {
126			return nil // the amend itself is prepared; folding is best-effort
127		}
128		defer repo.Close()
129		recordInheritedTrailers(ctx, s.inheritReplacedCommitsTrailers(ctx, repo, commitMsgFile, "commit"))
130		return nil
131	}
132	
133	// replacedCommits finds the commits the latest reset dropped: the tip HEAD left
134	// and the commits reachable from it that no branch, remote or HEAD still
135	// reaches. The reset is read from HEAD's reflog rather than ORIG_HEAD, which a
136	// later `git reset` to HEAD or `git stash` overwrites. Walking back from the
137	// newest entry, resets that did not move HEAD (unstaging, stash) are skipped,
138	// and commits made since count only while each of them redoes some of the
139	// dropped work; any other ref operation (checkout, merge, rebase, pull) means
140	// there is no redo in progress.
141	func replacedCommits(ctx context.Context, repo *git.Repository) (*object.Commit, []*object.Commit, string) {
142		var since []plumbing.Hash
143		var tipHash plumbing.Hash
144		for _, e := range headReflog(ctx) {
145			switch {
146			case strings.HasPrefix(e.msg, "commit"):
147				since = append(since, e.newHash)
148				continue
149			case strings.HasPrefix(e.msg, "reset:") && e.oldHash == e.newHash:
150				continue // unstaging or a stash: HEAD did not move
151			case strings.HasPrefix(e.msg, "reset:"):
152				tipHash = e.oldHash
153			default:
154				return nil, nil, "the latest ref operation was not a reset"
155			}
156			break
157		}
158		if tipHash.IsZero() {
159			return nil, nil, "no reset in HEAD's reflog"
160		}
161		tip, err := repo.CommitObject(tipHash)
162		if err != nil {
163			return nil, nil, "the reset's old HEAD is not a commit"
164		}
165		tipTree, err := tip.Tree()
166		if err != nil {
167			return nil, nil, "the reset's old HEAD has no tree"
168		}
169		// A commit since the reset that recommitted nothing at the old HEAD's
170		// content cannot have redone dropped work. Checked first, newest first,
171		// because it is the usual answer for every ordinary commit after a reset
172		// and it needs no subprocess or walk of the dropped commits.
173		sinceCommits := make([]*object.Commit, 0, len(since))
174		for _, h := range since {
175			c, err := repo.CommitObject(h)
176			if err != nil || !redoesDroppedWork(c, nil, tipTree) {
177				return nil, nil, "a commit since the reset redid none of the dropped work"
178			}
179			sinceCommits = append(sinceCommits, c)
180		}
181		dropped := unreachableCommits(ctx, repo, tipHash)
182		if len(dropped) == 0 {
183			return nil, nil, "the reset dropped nothing a branch does not still reach"
184		}
185		changed := changedPaths(dropped)
186		for _, c := range sinceCommits {
187			if !redoesDroppedWork(c, changed, tipTree) {
188				return nil, nil, "a commit since the reset redid none of the dropped work"
189			}
190		}
191		return tip, dropped, ""
192	}
193	
194	type reflogEntry struct {
195		oldHash, newHash plumbing.Hash
196		msg              string
197	}
198	
199	// maxReflogBytes bounds how much of HEAD's reflog a commit hook reads, and
200	// maxReflogEntries is the same bound, roughly, for the git fallback.
201	const (
202		maxReflogBytes   = 64 << 10
203		maxReflogEntries = 400
204	)
205	
206	// headReflog returns HEAD's most recent reflog entries, newest first, read
207	// from the per-worktree logs/HEAD so each entry carries the old and new HEAD.
208	func headReflog(ctx context.Context) []reflogEntry {
209		root, err := perWorktreeGitRoot(ctx)
210		if err != nil {
211			return nil
212		}
213		f, err := osroot.OpenNoFollow(root, "logs/HEAD")
214		if errors.Is(err, fs.ErrNotExist) {
215			// The reftable backend keeps reflogs in .git/reftable/, which only
216			// git reads; the files backend just has none yet.
217			return headReflogFromGit(ctx)
218		}
219		if err != nil {
220			return nil
221		}
222		defer f.Close()
223		info, err := f.Stat()
224		if err != nil {
225			return nil
226		}
227		offset := max(info.Size()-maxReflogBytes, 0)
228		data := make([]byte, info.Size()-offset)
229		if _, err := f.ReadAt(data, offset); err != nil && !errors.Is(err, io.EOF) {
230			return nil
231		}
232		lines := strings.Split(strings.ReplaceAll(string(data), "\r\n", "\n"), "\n")
233		if offset > 0 && len(lines) > 0 {
234			lines = lines[1:] // the first line may be cut
235		}
236		var out []reflogEntry
237		for i := len(lines) - 1; i >= 0; i-- {
238			head, msg, ok := strings.Cut(lines[i], "\t")
239			fields := strings.Fields(head)
240			if !ok || len(fields) < 2 || !plumbing.IsHash(fields[0]) || !plumbing.IsHash(fields[1]) {
241				continue
242			}
243			out = append(out, reflogEntry{oldHash: plumbing.NewHash(fields[0]), newHash: plumbing.NewHash(fields[1]), msg: msg})
244		}
245		return out
246	}
247	
248	// headReflogFromGit reads HEAD's reflog through git, for the reftable backend.
249	// git prints only each entry's new HEAD; an entry's old HEAD is the new HEAD of
250	// the entry before it.
251	func headReflogFromGit(ctx context.Context) []reflogEntry {
252		root, err := paths.WorktreeRoot(ctx)
253		if err != nil {
254			return nil
255		}
256		cmd := exec.CommandContext(ctx, "git", "reflog", "show", "-n", strconv.Itoa(maxReflogEntries), "--format=%H%x09%gs", "HEAD")
257		cmd.Dir = root
258		cmd.Env = gitrepo.EnvWithoutRepoOverrides()
259		out, err := cmd.Output()
260		if err != nil {
261			logging.Debug(logging.WithComponent(ctx, "checkpoint"), "prepare-commit-msg: could not read HEAD's reflog",
262				slog.String("error", err.Error()))
263			return nil
264		}
265		var entries []reflogEntry
266		lines := strings.Split(strings.TrimSpace(string(out)), "\n")
267		for i, line := range lines {
268			hash, msg, ok := strings.Cut(line, "\t")
269			if !ok || !plumbing.IsHash(hash) {
270				continue
271			}
272			e := reflogEntry{newHash: plumbing.NewHash(hash), msg: msg}
273			if i+1 < len(lines) {
274				if older, _, ok := strings.Cut(lines[i+1], "\t"); ok && plumbing.IsHash(older) {
275					e.oldHash = plumbing.NewHash(older)
276				}
277			}
278			entries = append(entries, e)
279		}
280		return entries
281	}
282	
283	// unreachableCommits lists the commits reachable from tip that HEAD, no remote
284	// and no other branch reaches: the work only the reset's old HEAD holds.
285	// Merged-in history and a teammate's commits still on another branch are never
286	// dropped. A branch pointing at tip itself is a backup of the very work being
287	// redone, so it does not count as still reaching it.
288	func unreachableCommits(ctx context.Context, repo *git.Repository, tip plumbing.Hash) []*object.Commit {
289		root, err := paths.WorktreeRoot(ctx)
290		if err != nil {
291			return nil
292		}
293		refsCmd := exec.CommandContext(ctx, "git", "for-each-ref", "--format=%(objectname)", "refs/heads", "refs/remotes")
294		refsCmd.Dir = root
295		refsCmd.Env = gitrepo.EnvWithoutRepoOverrides()
296		refs, err := refsCmd.Output()
297		if err != nil {
298			return nil
299		}
300		var exclude strings.Builder
301		exclude.WriteString("^HEAD\n")
302		for _, ref := range strings.Fields(string(refs)) {
303			if plumbing.IsHash(ref) && ref != tip.String() {
304				exclude.WriteString("^" + ref + "\n")
305			}
306		}
307		cmd := exec.CommandContext(ctx, "git", "rev-list", "--max-count="+strconv.Itoa(maxReplacedCommits), tip.String(), "--stdin")
308		cmd.Dir = root
309		cmd.Env = gitrepo.EnvWithoutRepoOverrides()
310		cmd.Stdin = strings.NewReader(exclude.String())
311		out, err := cmd.Output()
312		if err != nil {
313			return nil
314		}
315		var commits []*object.Commit
316		for _, line := range strings.Fields(string(out)) {
317			if !plumbing.IsHash(line) {
318				continue
319			}
320			if c, err := repo.CommitObject(plumbing.NewHash(line)); err == nil {
321				commits = append(commits, c)
322			}
323		}
324		return commits
325	}
326	
327	// changedPaths is every path the given commits changed relative to their first
328	// parent.
329	func changedPaths(commits []*object.Commit) map[string]bool {
330		out := make(map[string]bool)
331		for _, c := range commits {
332			changes, err := firstParentChanges(c)
333			if err != nil {
334				continue
335			}
336			for _, change := range changes {
337				for _, p := range []string{change.To.Name, change.From.Name} {
338					if p != "" {
339						out[p] = true
340					}
341				}
342			}
343		}
344		return out
345	}
346	
347	// redoesDroppedWork reports whether c recommitted a dropped path with the
348	// content it had at the reset's old HEAD. A nil dropped set accepts any path,
349	// the cheap necessary condition checked before the dropped commits are known.
350	func redoesDroppedWork(c *object.Commit, dropped map[string]bool, tipTree *object.Tree) bool {
351		changes, err := firstParentChanges(c)
352		if err != nil {
353			return false
354		}
355		tree, err := c.Tree()
356		if err != nil {
357			return false
358		}
359		for _, change := range changes {
360			for _, p := range []string{change.To.Name, change.From.Name} {
361				if p == "" || (dropped != nil && !dropped[p]) {
362					continue
363				}
364				want, wantAbsent, wantErr := findTreeEntry(tipTree, p)
365				got, gotAbsent, gotErr := findTreeEntry(tree, p)
366				if wantErr != nil || gotErr != nil {
367					continue
368				}
369				if wantAbsent == gotAbsent && (wantAbsent || want.Hash.Equal(got.Hash)) {
370					return true
371				}
372			}
373		}
374		return false
375	}
376	
377	func firstParentChanges(c *object.Commit) (object.Changes, error) {
378		tree, err := c.Tree()
379		if err != nil {
380			return nil, err //nolint:wrapcheck // callers only test for nil
381		}
382		parent, err := c.Parents().Next()
383		if err != nil {
384			return nil, err //nolint:wrapcheck // callers only test for nil
385		}
386		parentTree, err := parent.Tree()
387		if err != nil {
388			return nil, err //nolint:wrapcheck // callers only test for nil
389		}
390		return parentTree.Diff(tree) //nolint:wrapcheck // callers only test for nil
391	}
392	
393	type stagedEntry struct {
394		blob    plumbing.Hash
395		deleted bool
396	}
397	
398	// stagedBlobs maps each file staged against HEAD to what the commit index stages.
399	func stagedBlobs(ctx context.Context) (map[string]stagedEntry, error) {
400		changes, err := getStagedChanges(ctx)
401		if err != nil {
402			return nil, err
403		}
404		staged := make(map[string]stagedEntry, len(changes))
405		for _, c := range changes {
406			staged[c.path] = c.stagedEntry
407		}
408		return staged, nil
409	}
410	
411	// recommitsFilesOf reports whether c's work is what is staged: at least one
412	// file c changed is staged, and every staged file c changed has the content it
413	// had at the reset's old HEAD (tipTree).
414	func recommitsFilesOf(c *object.Commit, tipTree *object.Tree, staged map[string]stagedEntry) bool {
415		changes, err := firstParentChanges(c)
416		if err != nil {
417			return false
418		}
419		matched := false
420		for _, change := range changes {
421			// A rename can be partially staged as either the destination addition
422			// or the source deletion, so both endpoints can independently prove
423			// that part of the dropped commit is being redone.
424			for _, path := range []string{change.To.Name, change.From.Name} {
425				if path == "" {
426					continue
427				}
428				entry, ok := staged[path]
429				if !ok {
430					continue
431				}
432				tipEntry, absent, err := findTreeEntry(tipTree, path)
433				switch {
434				case err != nil:
435					return false
436				case entry.deleted && absent, !entry.deleted && !absent && tipEntry.Hash.Equal(entry.blob):
437					matched = true
438				default:
439					return false // staged, but rewritten: not this commit's work
440				}
441			}
442		}
443		return matched
444	}
445	
446	// findTreeEntry distinguishes an absent path from a tree-read failure. Walking
447	// one component at a time also makes a non-directory ancestor an ordinary
448	// absence instead of asking go-git to decode that blob as a tree.
449	func findTreeEntry(tree *object.Tree, path string) (*object.TreeEntry, bool, error) {
450		parts := strings.Split(path, "/")
451		for i, part := range parts {
452			entry, err := tree.FindEntry(part)
453			if errors.Is(err, object.ErrEntryNotFound) {
454				return nil, true, nil
455			}
456			if err != nil {
457				return nil, false, fmt.Errorf("find tree entry %q: %w", part, err)
458			}
459			if i == len(parts)-1 {
460				return entry, false, nil
461			}
462			if entry.Mode != filemode.Dir {
463				return nil, true, nil
464			}
465			tree, err = tree.Tree(part)
466			if err != nil {
467				return nil, false, fmt.Errorf("open tree %q: %w", part, err)
468			}
469		}
470		return nil, true, nil
471	}
