			}
			if !tc.inherits {
				require.NotContains(t, got, advForeignCheckpoint, "rewritten content is new work, not a redo")
				return
			}
			require.Contains(t, got, advForeignCheckpoint, "recommitting the dropped commit's content is a redo")
		})
	}
